document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('#contact-form');if(!f)return;f.addEventListener('submit',e=>{e.preventDefault();let ok=true;f.querySelectorAll('.error').forEach(x=>x.textContent='');[['name','お名前を入力してください。'],['email','メールアドレスを入力してください。'],['subject','件名を入力してください。'],['message','お問い合わせ内容を20文字以上で入力してください。']].forEach(([id,msg])=>{const el=document.getElementById(id);if(!el.value.trim()||(id==='message'&&el.value.trim().length<20)){el.closest('.field').querySelector('.error').textContent=msg;ok=false}});const mail=document.getElementById('email');if(mail.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(mail.value)){mail.closest('.field').querySelector('.error').textContent='正しいメールアドレスを入力してください。';ok=false}if(!document.getElementById('privacy').checked){document.getElementById('privacy-error').textContent='同意が必要です。';ok=false}if(ok)document.querySelector('.form-status').textContent='入力内容を確認しました。送信先APIを設定すると送信できます。'})});
